#!/usr/bin/env python3
"""Record actual image viewing and independently verify each prepared file."""
import fcntl,importlib.util,io
from pathlib import Path
from PIL import Image
s=importlib.util.spec_from_file_location('b',Path(__file__).with_name('continuous-warsaw-batch-000105.py'));b=importlib.util.module_from_spec(s);s.loader.exec_module(b);h=b.h;i=b.i
lock=(b.R/'worker.lock').open('a+');fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
observations={'455231': 'Original and derivative individually viewed. One tall icon with central female saint in red mantle and pale blue dress, halo, and narrative scenes on left, right and bottom. Complete supplied outer outline and all marginal scenes retained. One painting on three support boards; not separate scenes. Matches native IK 147. Source physical-dimension discrepancy retained in citation.', '456543': 'Original and derivative individually viewed. Large central red cross flanked by two richly dressed clergy, monks on left and crowned figures on right, elaborate architectural backdrop. Full supplied rectangular composition retained without cropping. Matches IK 157, distinct from IK 158 Trinity. Source reproduction has no photographic margin; its native ratio matches the documented tall support closely.', '559728': 'Original and derivative individually viewed. Complete irregular paper leaf and all margins visible; framed brightly colored scene of the Presentation, three architectural domes and a cross, figures holding Child, inscriptions at left and below. Pictorial image rather than a text-only leaf. One detached illuminated leaf, not entire codex. Tiny inscriptions and verso are not claimed as visually read.'}
files=[];decisions=[]
for r in i.selected(b.B)['rows']:
 im=h.load(i.folder(b.B)/'prepared'/(r['artwork_id']+'.json'));assert im['state']=='prepared';raw=Path(im['path']).read_bytes();orig=Path(im['original_path']).read_bytes();assert h.sha(raw)==im['sha256'] and h.sha(orig)==im['source_sha256'] and len(raw)==im['bytes']<=100000
 with Image.open(io.BytesIO(raw)) as pic:pic.load();assert pic.format=='JPEG' and pic.size==(im['width'],im['height'])
 with Image.open(io.BytesIO(orig)) as pic:pic.load();assert abs(pic.width/pic.height-im['width']/im['height'])<.03
 assert '/Documents/' not in im['original_path']
 decisions.append(dict(artwork_id=r['artwork_id'],source_id=r['native_id'],artist=r['creator_label'],sha256=im['sha256'],decision='accept',viewed_individually=True,viewed_path=im['path'],viewed_original_path=im['original_path'],original_sha256=im['source_sha256'],original_viewed_individually=True,tool='functions tools.view_image',observations=observations[r['native_id']],flag_resolution='Original and actual derivative individually viewed. The manual_visual_required switch conservatively flags the 315-pixel museum derivative, but the actual image is a complete authentic icon, not a placeholder. Full supplied frame, native inventory and source description match; no unseen reverse or tiny-inscription claim.',identity_confidence=.99,confidence_basis='Exact native object/image, inventory, dimensions, source description and observed physical composition; editorial judgment, not calibrated probability.'))
 files.append(dict(artwork_id=r['artwork_id'],sha256=im['sha256'],bytes=im['bytes'],complete_decode=True,proportions_preserved=True,original_sha256=im['source_sha256'],original_path=im['original_path']))
assert len(decisions)==3
review=dict(at=h.now(),batch_quality_decision='accept',reviewer='Codex actual image viewing',decisions=decisions,all_selected_files_individually_viewed=True,sample_only_files=[],limitations='Museum source images are 315 px wide. Compositions and complete supplied frames reviewed; no claim to inspect absent reverse views or tiny illegible inscriptions. All three originals and all three derivatives individually visually viewed, decoded and hashed.')
h.save(i.folder(b.B)/'visual-review.json',review);b.save('actual-visual-review.json',review);b.save('prewrite-file-verification.json',dict(at=h.now(),files=files,plan_sha256=h.pinned(b.PHASE)[1]))
print('3 actual per-image visual decisions and complete file checks saved')
